// Word + first-definition data ships embedded (gzip+base64) directly in this
// file so it works offline over file:// with no cross-origin fetch. Run
// `node scripts/embed-data.js` after editing data/words.json to refresh it.
const WORD_DATA_GZIP_B64 = "";
function compare_case_insensitive(a, b) {
  return a.toLowerCase().localeCompare(b.toLowerCase());
}

function base64_to_bytes(b64) {
  var binary = atob(b64);
  var bytes = new Uint8Array(binary.length);
  for (var i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

function inflate_word_data(b64) {
  var bytes = base64_to_bytes(b64);
  var stream = new Blob([bytes])
    .stream()
    .pipeThrough(new DecompressionStream("gzip"));
  return new Response(stream).text().then((text) => JSON.parse(text));
}

// Baked in by scripts/apply-config.js from config.toml.
const DICTIONARY_SIZE = 93000;
const IKIJIBIKI_THRESHOLD = 74399;

function load_word_data() {
  return inflate_word_data(WORD_DATA_GZIP_B64);
}

// Fisher-Yates partial shuffle: picks up to n random elements without replacement.
function sample_size(array, n) {
  var result = array.slice();
  var count = Math.min(n, result.length);
  for (var i = 0; i < count; i++) {
    var j = i + Math.floor(Math.random() * (result.length - i));
    var tmp = result[i];
    result[i] = result[j];
    result[j] = tmp;
  }
  return result.slice(0, count);
}

function pick_random_words(entries, n) {
  return sample_size(entries, n).sort((a, b) =>
    compare_case_insensitive(a.word, b.word),
  );
}

function find_definition(entries, word) {
  return entries.find(
    (entry) => compare_case_insensitive(entry.word, word) === 0,
  );
}

function build_word_li(word) {
  return `<li><span class="word">${word}</span>
  <span class="lookup">?</span></li>`;
}

function build_word_lis(words) {
  return `${words.map(build_word_li).join("\n")}`;
}

function setDisplay(element, display) {
  element.style.display = display;
}

function wordnik_word_url(word) {
  return `https://www.wordnik.com/words/${encodeURIComponent(word)}`;
}

function escape_html(str) {
  var div = document.createElement("div");
  div.textContent = str;
  return div.innerHTML;
}

// Renders definition text as safe HTML, turning <xref>word</xref> markup into
// links to that word's Wordnik page; any other tags are dropped to plain text.
function node_to_definition_html(node) {
  if (node.nodeType === Node.TEXT_NODE) {
    return escape_html(node.textContent);
  }
  if (node.tagName === "XREF") {
    var word = node.textContent;
    return `<a href="${escape_html(wordnik_word_url(word))}" class="xref">${escape_html(word)}</a>`;
  }
  return Array.from(node.childNodes).map(node_to_definition_html).join("");
}

function build_definition_html(text) {
  var dom = new DOMParser().parseFromString(text || "", "text/html");
  return Array.from(dom.body.childNodes).map(node_to_definition_html).join("");
}

function set_definition(definition, attributions) {
  var definition_word = document.getElementById("definition_word");
  var definition_text = document.getElementById("definition_text");
  var definition_attribution = document.getElementById(
    "definition_attribution",
  );
  var definition_link = document.getElementById("definition_link");
  definition_word.innerText = definition.word;
  definition_text.innerHTML = build_definition_html(definition.def);
  definition_attribution.innerText = attributions[definition.attr_i];
  definition_link.href = wordnik_word_url(definition.word);
}

function show_definition(word, entries, attributions) {
  var definition = find_definition(entries, word);
  var def = document.getElementById("definition");
  def.classList.add("visible");
  set_definition(definition, attributions);
}

function estimateVocabularySizeGiven(n) {
  return Math.round(document.dictionarySize * (n / document.sampleSize));
}

// Zero-pads to digit_width digits, then adds thousands separators, e.g. 930 -> "00,930".
function pad_with_commas(value, digit_width) {
  var digits = String(value).padStart(digit_width, "0");
  return digits.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

// Same as pad_with_commas, but wraps the leading zero padding in a span so it
// can be styled lighter than the significant digits.
function pad_with_commas_html(value, digit_width) {
  var formatted = pad_with_commas(value, digit_width);
  var significant = value.toLocaleString();
  if (!formatted.endsWith(significant)) return formatted;
  var pad = formatted.slice(0, formatted.length - significant.length);
  return `<span class="pad-zero">${pad}</span>${significant}`;
}

function get_preferred_theme() {
  var saved = localStorage.getItem("ikijibiki_theme");
  if (saved === "dark" || saved === "light") return saved;
  return window.matchMedia("(prefers-color-scheme: dark)").matches
    ? "dark"
    : "light";
}

function apply_theme(theme) {
  document.documentElement.dataset.theme = theme;
  var toggle = document.getElementById("theme_toggle");
  if (toggle) toggle.textContent = theme === "dark" ? "☀️" : "🌙";
}

// Applied immediately (not just in go()) so the page doesn't flash the wrong theme.
apply_theme(get_preferred_theme());

function spawn_confetti() {
  var colors = ["#1980d7", "#ff5401", "#333333"];
  var container = document.createElement("div");
  container.className = "confetti_container";
  document.body.appendChild(container);
  for (var i = 0; i < 24; i++) {
    var piece = document.createElement("span");
    piece.className = "confetti_piece";
    piece.style.left = Math.random() * 100 + "%";
    piece.style.backgroundColor = colors[i % colors.length];
    piece.style.animationDelay = Math.random() * 0.3 + "s";
    piece.style.transform = `rotate(${Math.random() * 360}deg)`;
    container.appendChild(piece);
  }
  setTimeout(function () {
    container.remove();
  }, 1800);
}

function ready(fn) {
  if (document.readyState != "loading") {
    fn();
  } else {
    document.addEventListener("DOMContentLoaded", fn);
  }
}

function go() {
  console.log("setting up");
  document.dictionarySize = DICTIONARY_SIZE; // total words Wordnik has definitions for
  document.ikijibikiActive = false;
  var theme_toggle = document.getElementById("theme_toggle");
  apply_theme(document.documentElement.dataset.theme || get_preferred_theme());
  theme_toggle.addEventListener("click", function () {
    var next =
      document.documentElement.dataset.theme === "dark" ? "light" : "dark";
    localStorage.setItem("ikijibiki_theme", next);
    apply_theme(next);
  });
  var according = document.getElementById("according");
  document.getElementById("estimated_vocabulary_size").innerHTML =
    pad_with_commas_html(0, String(document.dictionarySize).length);
  var progress_threshold = document.getElementById("progress_threshold");
  progress_threshold.style.left =
    Math.min(100, (IKIJIBIKI_THRESHOLD / document.dictionarySize) * 100) + "%";
  setDisplay(according, "block");
  var word_list = document.getElementById("wordlist");
  setDisplay(word_list, "none");
  load_word_data().then(({ entries, attributions }) => {
    document.sampleSize = Math.min(100, entries.length); // words actually shown, i.e. n
    var words = pick_random_words(entries, document.sampleSize).map(
      (entry) => entry.word,
    );
    word_list.innerHTML = build_word_lis(words);
    setDisplay(word_list, "flex");
    void word_list.offsetHeight; // force reflow so the opacity transition below actually animates
    word_list.classList.add("loaded");
    //-
    spans = document.querySelectorAll("li span.lookup");
    spans.forEach((el) => {
      el.addEventListener(
        "click",
        function () {
          word = el.parentElement.querySelector(".word").innerText;
          show_definition(word, entries, attributions);
        },
        false,
      );
    });
    // set up click handler for words
    spans = document.querySelectorAll("li span.word");
    spans.forEach((el) => {
      el.addEventListener("click", function () {
        el.classList.toggle("highlight");
        show_definition(el.innerText, entries, attributions);
        words_selected = document.querySelectorAll(".highlight").length;
        estimated_vocabulary_size = estimateVocabularySizeGiven(words_selected);
        estimated_vocabulary_size_text = pad_with_commas_html(
          estimated_vocabulary_size,
          String(document.dictionarySize).length,
        );
        word_el = document.getElementById("estimated_vocabulary_size");
        word_el.innerHTML = estimated_vocabulary_size_text;
        var progress_fill = document.getElementById("progress_fill");
        var progress_percent = Math.min(
          100,
          (estimated_vocabulary_size / document.dictionarySize) * 100,
        );
        progress_fill.style.width = progress_percent + "%";
        var progress_label = document.getElementById("progress_label");
        progress_label.innerText =
          progress_percent.toFixed(1) + "% of the dictionary";
        ikijibiki_el = document.getElementById("ikijibiki");
        if (estimated_vocabulary_size > IKIJIBIKI_THRESHOLD) {
          ikijibiki_el.innerText =
            "You are a walking dictionary! an Ikijibiki!! 🚶 📖 ";
          setDisplay(ikijibiki_el, "block");
          if (!document.ikijibikiActive) {
            document.ikijibikiActive = true;
            spawn_confetti();
          }
        } else {
          setDisplay(ikijibiki_el, "none");
          document.ikijibikiActive = false;
        }
      });
    }, false);
    // finish up
  });
  console.log("set up");
}

ready(go);
